/* ==GenubarStyle==
 * @id              nordic_frost_style
 * @name            Nordic Frost Panel
 * @version         1.0.0
 * @author          genubar-themes
 * @description     Cool arctic slate accent styling for Genubar panel buttons
 * @min_app_version 0.1.0
 * ==/GenubarStyle== */

.panel-button.genubar-panel-button {
    -natural-hpadding: 7px;
    -minimum-hpadding: 4px;
    border-radius: 6px;
}

.panel-button.genubar-panel-button:hover,
.panel-button.genubar-panel-button:active,
.panel-button.genubar-panel-button:checked {
    background-color: rgba(136, 192, 208, 0.22);
    color: #eceff4;
}

.genubar-app-button {
    font-weight: 700;
    color: #88c0d0;
}
